	return (
		<section className="flex">
			<div className="relative my-4 aspect-square w-[300px] overflow-hidden rounded-[4px]">
				<Image
					src="/itjustworks.jpg"
					width={100}
					height={100}
					alt="Benjamin Spiers - Moonlight 2023"
					className="absolute inset-0"
